require "test_helper"

class TimeHelperTest < ActionView::TestCase
  def parse(html)
    Nokogiri::HTML::DocumentFragment.parse(html)
  end

  test "local_time_tag sends the raw timestamp for the browser to format" do
    time = Time.utc(2024, 9, 12, 17, 42, 0)
    html = parse(local_time_tag(time))

    assert_select html, "time.local-time-value" do |elements|
      element = elements.first
      assert_equal "2024-09-12T17:42:00Z", element["datetime"]
      assert_equal "local-time", element["data-controller"]
      assert_equal "2024-09-12T17:42:00Z", element.text
      assert_nil element["data-local-time-format-value"]
    end
  end

  test "local_time_tag accepts a format for absolute dates and times" do
    time = Time.utc(2024, 9, 12, 17, 42, 0)
    html = parse(local_time_tag(time, format: :date, class: "card__timestamp"))

    assert_select html, "time.local-time-value.card__timestamp" do |elements|
      element = elements.first
      assert_equal "date", element["data-local-time-format-value"]
      assert_equal "local-time", element["data-controller"]
    end
  end

  test "local_time_tag merges extra stimulus controllers" do
    time = Time.utc(2024, 9, 12, 17, 42, 0)
    html = parse(local_time_tag(time, data: { controller: "tooltip" }))

    assert_select html, "time[data-controller='local-time tooltip']"
  end

test "local_time_tag always emits UTC so HTML can be cached across timezones" do
  time = Time.utc(2024, 9, 12, 17, 42, 0)

  eastern = Time.use_zone("America/New_York") { local_time_tag(time) }
  tokyo = Time.use_zone("Asia/Tokyo") { local_time_tag(time) }

  assert_equal eastern, tokyo
  assert_includes eastern, %(datetime="2024-09-12T17:42:00Z")
end
end
==== date_helpers ====
import { getMetaContent } from "helpers/meta_helpers"

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

export function relativeTimeInWords(date, now = new Date()) {
  const days = signedLocalDayDifference(now, date)

  if (days === 0) {
    if (date < now) {
      return formatClockTime(date)
    } else {
      return "today"
    }
  } else if (days === 1) {
    return "tomorrow"
  } else if (days === -1) {
    return "yesterday"
  } else if (days > 1) {
    return `in ${days} days`
  } else if (days > -7) {
    return `${-days} days ago`
  } else {
    return formatShortDate(date, now)
  }
}

export function formatClockTime(date) {
  return date.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })
}

export function formatShortDate(date, now = new Date()) {
  const options = { month: "short", day: "numeric" }

  if (date.getFullYear() !== now.getFullYear()) {
    options.year = "numeric"
  }

  return date.toLocaleDateString("en-US", options)
}

export function formatWeekdayDate(date) {
  return date.toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" })
}

export function formatFullDateTime(date) {
  return date.toLocaleString("en-US", { dateStyle: "full", timeStyle: "short" })
}

function signedLocalDayDifference(fromDate, toDate) {
  return Math.round((beginningOfLocalDay(toDate) - beginningOfLocalDay(fromDate)) / (1000 * 60 * 60 * 24))
}

function beginningOfLocalDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

// Snap a timestamp to midnight using the timezone the server rendered with (the
// `timezone` meta tag), so client day boundaries match the server's instead of
// following the browser's resolved timezone, which can differ in a PWA.
function datePartsInTimezone(date) {
  return dateFormatter().formatToParts(date).reduce((parts, { type, value }) => {
    if (type !== "literal") parts[type] = parseInt(value, 10)
    return parts
  }, {})
}

let dateFormatterCache
let dateFormatterTimezone

function dateFormatter() {
  const timezone = getMetaContent("timezone")

  if (!dateFormatterCache || dateFormatterTimezone !== timezone) {
    dateFormatterTimezone = timezone
    dateFormatterCache = buildDateFormatter(timezone)
  }

  return dateFormatterCache
}

function buildDateFormatter(timezone) {
  const options = { year: "numeric", month: "2-digit", day: "2-digit" }

  try {
    return new Intl.DateTimeFormat("en-US", { ...options, timeZone: timezone })
  } catch {
    return new Intl.DateTimeFormat("en-US", options)
  }
}
